export type ParsedDelegatePriceBookInstruction<
  TProgram extends string = typeof BULLXI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    bufferPda: TAccountMetas[1];
    delegationRecordPda: TAccountMetas[2];
    delegationMetadataPda: TAccountMetas[3];
    pda: TAccountMetas[4];
    ownerProgram: TAccountMetas[5];
    delegationProgram: TAccountMetas[6];
    systemProgram: TAccountMetas[7];
  };
  data: DelegatePriceBookInstructionData;
};

export function parseDelegatePriceBookInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDelegatePriceBookInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      bufferPda: getNextAccount(),
      delegationRecordPda: getNextAccount(),
      delegationMetadataPda: getNextAccount(),
      pda: getNextAccount(),
      ownerProgram: getNextAccount(),
      delegationProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDelegatePriceBookInstructionDataDecoder().decode(instruction.data),
  };
}
